WITH base AS (SELECT *, ROUND(unit_price, 1) AS unit_price_rounded FROM order_items WHERE product_id IS NOT NULL), latest AS (SELECT * FROM base QUALIFY ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY quantity DESC NULLS LAST, id) = 1), with_dims AS (SELECT s.id, s.order_id, s.product_id, s.quantity, o.status FROM latest s LEFT JOIN orders o ON s.order_id = o.id), with_windows AS (SELECT id, order_id, product_id, status, LEAD(quantity, 1) OVER w_recent AS next_quantity, NTILE(4) OVER w_recent AS quantity_bucket FROM with_dims WHERE status IN ('CANCELLED', 'RETURNED', 'SHIPPED') WINDOW w_recent AS (ORDER BY quantity, id)), metrics AS (SELECT id, order_id, product_id, status, quantity_bucket, AVG(next_quantity) OVER (PARTITION BY order_id ORDER BY next_quantity, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS next_quantity_avg_3, LAG(quantity_bucket, 2, 0) OVER (PARTITION BY order_id ORDER BY next_quantity, id) AS prev_quantity_bucket, AVG(next_quantity) OVER w_part AS next_quantity_avg_2_prior FROM with_windows WINDOW w_part AS (ORDER BY next_quantity, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING)), enriched AS (SELECT s.*, o.order_date, o.status AS order_status, o.channel FROM metrics s LEFT JOIN orders o ON s.order_id = o.id) SELECT s.id, s.product_id, s.status, s.next_quantity_avg_3, s.next_quantity_avg_2_prior, s.channel, CASE WHEN channel RLIKE '^(partner|web)$' THEN 'PRIORITY' WHEN channel RLIKE '^(mobile|store)$' THEN 'EXTENDED' ELSE 'OTHER_ZONE' END AS channel_zone, (SELECT AVG(x.revenue) FROM store_sales x WHERE x.product_id = s.product_id) AS avg_store_sale_revenue FROM enriched s;
